INSERT INTO public.dfm_rulesets (version, rules, active, notes, created_at) VALUES ('dfm-2026.10-r1', '{"rules": {"min_feature": {"source": "materials.min_feature_ratio x t, floor materials.min_feature_floor_mm", "severity": "BLOCKING"}, "hole_to_bend": {"ratio": 2.5, "severity": "WARNING", "addBendRadius": true}, "hole_to_edge": {"source": "materials.hole_to_edge_ratio x t", "severity": "WARNING", "blockingBelowRatio": 0.5}, "open_contour": {"severity": "BLOCKING", "closeToleranceMm": 0.01}, "part_size_max": {"source": "thickness_options.max_part_*_mm", "severity": "BLOCKING"}, "part_size_min": {"minMm": 10, "severity": "BLOCKING"}, "text_entities": {"message": "Convert text to outlines or a stencil font", "severity": "WARNING"}, "bend_flange_min": {"source": "thickness_options.min_flange_ratio x t", "severity": "BLOCKING"}, "min_hole_diameter": {"source": "materials.min_hole_ratio x t, floor materials.min_hole_floor_mm", "severity": "BLOCKING"}, "bend_not_supported": {"when": "bend lines present and thickness option not bendable or no bending service", "severity": "BLOCKING"}}, "weights": {"WARNING": 8, "BLOCKING": 30}}', true, 'R1 default thresholds (to be calibrated)', '2026-10-10 16:18:41.585421+00') ON CONFLICT DO NOTHING;
